changeSet.sql:
ALTER procedure [asset].[BulkDelete] @uid uniqueidentifier, @r int as begin set nocount on;
create table #h (IntersectID int, ID bigint, Object varchar(50), ObjectID int, [Uid] uniqueidentifier, Processed bit null); create table #w (ItemID int); declare @Obj varchar(50), @ObjID int, @dt datetime = getutcdate(), @predicateType int = 0;
begin -- Set variables select @Obj = Object, @ObjID = ObjectID from AssetType where Uid = @uid;
if @Obj = 'ArtifactType' or @Obj = 'FusionAttributeType' or @Obj = 'ReferenceItemType' begin set @predicateType = 3 end; if @Obj = 'PolicyType' or @Obj = 'TaxonomyType' begin set @predicateType = 4 end; end
begin -- Resolve data about incoming assets, and any errors. update T set T.AssetID = S.ID from #AssetTable T inner join Asset S on S.Uid = T.Uid inner join AssetType ST on ST.Uid = @uid and ST.ID = S.AssetTypeID;
update #AssetTable set Success = 0, [Message] = coalesce([Message] + '; ', '') + 'You must provide a valid Uid for this asset when you are attempting to delete it' where [Uid] is null or [Uid] = CAST(CAST(0 AS BINARY) AS UNIQUEIDENTIFIER);
update #AssetTable set Success = 0, [Message] = coalesce([Message] + '; ', '') + 'Not found based on Uid provided' where AssetID is null; end
begin -- Add to working table. insert into #h select null, T.ID, T.Object, T.ObjectID, T.[Uid], 0 from Asset T inner join #AssetTable S on S.Uid = T.Uid and S.Success is null; end
begin -- Get children to also deal with. if @predicateType > 0 begin while exists(select 1 from #h where Processed = 0) begin insert into #h select I.IntersectID, C.ID, C.Object, C.ObjectID, C.[Uid], null from #h P inner join PredicateIntersect I on I.PredicateType = @predicateType and I.Subject = P.Object and I.SubjectID = P.ObjectID and P.Processed = 0 inner join Asset C on C.Object = I.Object and C.ObjectID = I.ObjectID;
update #h set Processed = 1 where Processed = 0; update #h set Processed = 0 where Processed is null; end end end
begin -- Get any workflow items we need to delete. insert into #w select distinct wi.ID from workflow.[Type] wt inner join workflow.EventRegistration we on we.typeid = wt.id and we.changetype <> 3 inner join workflow.[Version] wv on wt.id = wv.typeId inner join workflow.Item wi on wv.id = wi.VersionID inner join #h S on S.Object = wi.Object and S.ObjectID = wi.ObjectID;
insert into #w select wi.id from workflow.Item wi inner join Issue i on wi.object = 'Issue' and i.id = wi.objectid inner join #h S on S.Object = i.Object and S.ObjectID = i.ObjectID; end
begin try begin -- Insert into indexer queue. INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) select distinct 'ObjectIndex', 'D', Object, ObjectID, ID from #h; end
begin -- Insert into audit. insert into reporting.Global_Audit (Object, ObjectID, ObjectName, ResourceID, Date, Action, ActionObject, ActionObjectID, ActionObjectTypeName, ActionObjectName, ActionDescription) select distinct O.Object, O.ObjectID, SUBSTRING(O.DisplayValue,1,250), @r, @dt, 'Deleted', O.Object, O.ObjectID, O.TypeName, SUBSTRING(O.DisplayValue,1,250), 'This asset has been removed.' from AssetDetail O inner join #h I on O.ID = I.ID; end
begin -- Delete from cross reference. delete T from AssetCrossReference T inner join #h S on S.[Uid] = T.[Uid]; end
begin -- Delete from core table, depending on type if @Obj = 'ArtifactType' begin delete Artifact where ID in (select ObjectID from #h); end
if @Obj = 'FusionAttributeType' begin delete FusionAttribute where ID in (select ObjectID from #h); end
if @Obj = 'PolicyType' begin delete [Policy] where ID in (select ObjectID from #h); end
if @Obj = 'ReferenceItemType' begin delete ReferenceItem where ID in (select ObjectID from #h); end
if @Obj = 'RuleType' begin delete [Rule] where ID in (select ObjectID from #h); end
if @Obj = 'TaxonomyType' begin delete Taxonomy where ID in (select ObjectID from #h); end end
begin -- Delete attributes. delete T from Field T inner join [Attribute] A on T.ObjectType = 'Attribute' and A.ID = T.ObjectID inner join #h S on S.Object = A.ObjectType and S.ObjectID = A.ObjectID;
delete T from [Attribute] T inner join #h S on S.Object = T.ObjectType and S.ObjectID = T.ObjectID; end
begin -- Delete parent/child relationships if @predicateType > 0 begin delete T from [Intersect] T inner join #h S on S.IntersectID = T.ID; end end
begin -- Delete where is Subject side of relationship. delete T from [Intersect] T inner join #h S on S.Object = T.Subject and S.ObjectID = T.SubjectID; end
begin -- Delete where is Object side of relationship. delete T from [Intersect] T inner join #h S on S.Object = T.Object and S.ObjectID = T.ObjectID; end
begin -- Delete comments delete T from CommentRelation T inner join #h S on S.Object = T.ObjectType and S.ObjectID = T.ObjectID;
delete T from CommentVote T inner join Comment C on C.ID = T.CommentID inner join #h S on S.Object = C.OwnerObjectType and S.ObjectID = C.OwnerObjectID;
delete T from Comment T inner join #h S on S.Object = T.OwnerObjectType and S.ObjectID = T.OwnerObjectID; end
begin -- Delete favorites delete T from Favorite T inner join #h S on S.Object = T.Object and S.ObjectID = T.ObjectID; end
begin -- Delete follows delete T from Follow T inner join #h S on S.Object = T.ObjectType and S.ObjectID = T.ObjectID; end
begin -- Delete fields delete T from Field T inner join #h S on S.Object = T.ObjectType and S.ObjectID = T.ObjectID; end
begin -- Delete issues delete T from Issue T inner join #h S on S.Object = T.Object and S.ObjectID = T.ObjectID; end
begin -- Delete nyms delete T from Nym T inner join #h S on S.Object = T.Object and S.ObjectID = T.ObjectID; end
begin -- Delete responsibilities. delete T from ResponsibilityTypeRelationOverrideItem T inner join #h S on S.ID = T.AssetID;
delete T from ResponsibilityTypeRelationRuleResult T inner join #h S on S.ID = T.AssetID; end
begin -- Delete workflows delete T from [workflow].[ItemAssignment] T inner join #w S on S.ItemID = T.ItemID;
delete T from [workflow].[ItemStepTransition] T inner join workflow.itemstep wis on (wis.ID = T.ToItemStepID or wis.ID = T.FromItemStepID) inner join #w S on S.ItemID = wis.ItemID;
delete workflow.itemstep where ItemID in (Select ItemID from #w);
delete [workflow].[Item] where ID in (Select ItemID from #w); end
begin -- Update return table. update #AssetTable set Success = 1 where Success is null and AssetID is not null; end end try begin catch DECLARE @ErrorMessage NVARCHAR(4000) SELECT @ErrorMessage = ERROR_MESSAGE()
update #AssetTable set Success = 0, [Message] = @ErrorMessage where Success is null and AssetID is not null; end catch
select * from #AssetTable end

changeSet.rollback:
ALTER procedure [asset].[BulkDelete]

	@uid uniqueidentifier,
	@r int
as
begin
	set nocount on;

	update	T
	set		T.AssetID = S.ID
	from	#AssetTable T
			inner join Asset S on S.Uid = T.Uid
			inner join AssetType ST on ST.Uid = @uid and ST.ID = S.AssetTypeID;


	update	#AssetTable
	set		Success = 0,
			[Message] = coalesce([Message] + '; ', '') + 'You must provide a valid Uid for this asset when you are attempting to delete it'
	where	[Uid] is null or [Uid] = CAST(CAST(0 AS BINARY) AS UNIQUEIDENTIFIER); 

	update	#AssetTable
	set		Success = 0,
			[Message] = coalesce([Message] + '; ', '') + 'Not found based on Uid provided'
	where	AssetID is null;



	drop table if exists #ObjectMergeTableResult;
	create table #ObjectMergeTableResult (ID int, ItemNumber int, [Action] nvarchar(10));
	CREATE NONCLUSTERED INDEX IX_TempObjectMergeTableResult ON #ObjectMergeTableResult ( ItemNumber ASC );

	declare @current int = 1,	
			@max int = 0

	select @max = max(ItemNumber) from #AssetTable

	while @current <= @max
	begin
		if exists(select ItemNumber from #AssetTable where ItemNumber = @current and Success is null)
		begin
			declare @assetId bigint;
			select @assetId = AssetID from #AssetTable where ItemNumber = @current
			exec DeleteAssetById @assetId, @r
		end
		set @current = @current + 1
	end

	update	#AssetTable
	set		Success = 1
	where	Success is null
			and AssetID is not null;

	select * from #AssetTable
end
